use genex::prelude::*;

/// The sight's notch in the gun's own space; ADS moves the gun so this point lands on the camera axis.
const SIGHT: Vec3 = Vec3::new(0.0, 0.052, -0.02);
const HIP: Vec3 = Vec3::new(0.17, -0.19, 0.45);
const ADS_DEPTH: f32 = 0.32;
const ADS_SECONDS: f32 = 0.15;

/// Where the gun sits in camera space at `aim` (0 hip, 1 down the sights).
fn gun_local(aim: f32) -> Vec3 {
    let sights = vec3(-SIGHT.x, -SIGHT.y, ADS_DEPTH); // the notch on the axis, not tuned by eye
    HIP.lerp(sights, aim)
}

fn update_aim(w: &mut super::World, ctx: &Ctx) {
    let target = if w.aim_held { 1.0 } else { 0.0 };
    let step = ctx.dt / ADS_SECONDS;
    w.aim = (w.aim + (target - w.aim).clamp(-step, step)).clamp(0.0, 1.0);
}

/// One predicate the HUD and the demo share: the crosshair is drawn only while not aiming.
pub fn crosshair_visible(w: &super::World) -> bool { w.aim < 0.5 }

fn ads_demo(d: &mut DemoDriver<super::World>) -> Value {
    d.sim_mut().world.aim_held = true;
    d.advance_ms(400);
    let w = &d.sim().world;
    // The notch in camera space: x, y over depth is its offset from the screen's centre.
    let notch = gun_local(w.aim) + SIGHT;
    json!({
        "sightNdc": { "x": notch.x / notch.z, "y": notch.y / notch.z },
        "crosshairVisible": crosshair_visible(w),
    })
}
